mapper.update:
UPDATE credential_file_batch
SET status = #{status},
    uploaded_at = #{uploadedAt}
WHERE upload_batch_id = #{uploadBatchId}
  AND status = 'UPLOADING'

UPDATE credential_file_batch
SET status = 'FAILED',
    converted_file_count = #{convertedFileCount},
    error_message = #{errorMessage}
WHERE upload_batch_id = #{uploadBatchId}
  AND status = 'CONVERTING'
